package bowling

import "errors"

var (
	errNegativeRoll   = errors.New("Negative roll is invalid")
	errTooManyPins    = errors.New("Pin count exceeds pins on the lane")
	errGameOver       = errors.New("Cannot roll after game is over")
	errIncompleteGame = errors.New("Score cannot be taken until the end of the game")
)

// Game keeps track of a game of bowling.
type Game struct {
	rolls        []int // every roll, in order
	frame        int   // current frame, 0-9
	rollsInFrame int   // rolls made in the current frame
	pinsInFrame  int   // pins knocked down in the first roll of the current frame
	lanePins     int   // pins still standing on the lane for the next roll
	gameOver     bool
}

// NewGame returns a new, empty bowling game.
func NewGame() *Game {
	return &Game{
		rolls:    []int{},
		lanePins: 10,
	}
}

// Roll records a throw that knocked down the given number of pins.
func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errNegativeRoll
	}
	if pins > 10 {
		return errTooManyPins
	}
	if g.gameOver {
		return errGameOver
	}

	if g.frame < 9 {
		return g.rollInRegularFrame(pins)
	}
	return g.rollInTenthFrame(pins)
}

// rollInRegularFrame handles frames 1-9.
func (g *Game) rollInRegularFrame(pins int) error {
	if g.rollsInFrame == 0 {
		// First roll: any number of pins is fine.
		g.rolls = append(g.rolls, pins)
		g.pinsInFrame = pins
		g.lanePins = 10 - pins
		if pins == 10 {
			g.advanceFrame()
		} else {
			g.rollsInFrame = 1
		}
		return nil
	}
	// Second roll: cannot knock down more pins than are standing.
	if pins > g.lanePins {
		return errTooManyPins
	}
	g.rolls = append(g.rolls, pins)
	g.advanceFrame()
	return nil
}

// rollInTenthFrame handles the tenth frame, including its bonus rolls.
func (g *Game) rollInTenthFrame(pins int) error {
	switch g.rollsInFrame {
	case 0:
		// First roll of the tenth frame.
		g.rolls = append(g.rolls, pins)
		g.pinsInFrame = pins
		g.rollsInFrame = 1
		g.lanePins = 10 - pins
		if pins == 10 {
			// Strike: the lane resets for the bonus rolls.
			g.lanePins = 10
		}
		return nil
	case 1:
		if g.pinsInFrame == 10 {
			// First bonus roll after a strike: the lane is full.
			g.rolls = append(g.rolls, pins)
			g.rollsInFrame = 2
			g.lanePins = 10 - pins
			if pins == 10 {
				g.lanePins = 10
			}
			return nil
		}
		if pins > g.lanePins {
			return errTooManyPins
		}
		g.rolls = append(g.rolls, pins)
		g.rollsInFrame = 2
		if pins == g.lanePins {
			// Spare: the lane resets for the bonus roll.
			g.lanePins = 10
		} else {
			// Open frame: the game is over.
			g.gameOver = true
		}
		return nil
	default:
		// Final bonus roll.
		if pins > g.lanePins {
			return errTooManyPins
		}
		g.rolls = append(g.rolls, pins)
		g.gameOver = true
		return nil
	}
}

func (g *Game) advanceFrame() {
	g.frame++
	g.rollsInFrame = 0
	g.pinsInFrame = 0
	g.lanePins = 10
}

// Score returns the total score for a completed game.
func (g *Game) Score() (int, error) {
	if !g.gameOver {
		return 0, errIncompleteGame
	}

	total := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		if frame < 9 {
			if g.rolls[i] == 10 {
				// Strike: 10 plus the next two rolls.
				total += 10 + g.rolls[i+1] + g.rolls[i+2]
				i++
			} else if g.rolls[i]+g.rolls[i+1] == 10 {
				// Spare: 10 plus the next roll.
				total += 10 + g.rolls[i+2]
				i += 2
			} else {
				total += g.rolls[i] + g.rolls[i+1]
				i += 2
			}
		} else {
			// Tenth frame: the total of all its rolls.
			for i < len(g.rolls) {
				total += g.rolls[i]
				i++
			}
		}
	}
	return total, nil
}

